('earpods-usbc-lux', '{"id":"earpods-usbc-lux","name":"Наушники USB-C с микрофоном (Lux-качество)","brand":"","category":"headphones","price":2499,"oldPrice":null,"description":"Новое поступление. Чистый звук, удобный разъём USB-C и микрофон для звонков.\nЦена 2 499 ₸ с учётом кабеля USB–USB C. При самовывозе из магазина — 2 000 ₸.","images":["assets/products/earpods-usbc.webp"],"specifications":{"connection":"USB-C","kit":"наушники, кабель USB–USB C"},"availability":"in_stock","featured":true,"isNew":true,"isSale":false}'::jsonb),
('charger-usbc-20w', '{"id":"charger-usbc-20w","name":"Сетевое зарядное устройство USB-C 20 Вт","brand":"","category":"chargers","price":7990,"oldPrice":null,"description":"Быстрая, безопасная зарядка для смартфонов и другой техники.\nЗаряжает смартфон от 0% до 50% примерно за 30 минут. Защита от перегрева, перепадов напряжения и короткого замыкания. Подходит для iPhone (8 и новее), iPad, AirPods и других устройств с USB-C.","images":["assets/products/charger-20w-1.webp","assets/products/charger-20w-2.webp"],"specifications":{"power":"20 Вт","connector":"USB-C","kit":"адаптер 20 Вт, фирменная упаковка"},"availability":"in_stock","featured":true,"isNew":false,"isSale":false}'::jsonb),
('cable-usbc-1m', '{"id":"cable-usbc-1m","name":"Кабель USB-C — Lightning / USB-C — USB-C, 1 м","brand":"","category":"cables","price":4990,"oldPrice":null,"description":"Быстрая и безопасная зарядка без нагрева и сбоев. Встроенные чипы защиты, поддержка быстрой зарядки и стабильная передача данных.\nДве версии: USB-C — Lightning (iPhone 8–14, iPad, AirPods) и USB-C — USB-C (iPhone 15 / 16, iPad, Android и другие современные устройства).","images":["assets/products/cable-usbc-1m.webp"],"specifications":{"length":"1 м","versions":"USB-C — Lightning; USB-C — USB-C"},"availability":"in_stock","featured":true,"isNew":false,"isSale":false}'::jsonb),
('watch-w26-3in1', '{"id":"watch-w26-3in1","name":"Набор 3 в 1: смарт-часы W26 Pro Max Special + наушники + ремешки","brand":"Watch+","category":"watches","price":4490,"oldPrice":null,"description":"Стильный комплект на каждый день и хороший подарок.\nСмарт-часы: вызовы, сообщения, пульс, спорт-режимы. Беспроводные наушники: чистый звук и быстрое подключение. В комплекте два ремешка — классический и спортивный.","images":["assets/products/watch-w26.webp"],"specifications":{"kit":"смарт-часы, беспроводные наушники, 2 ремешка"},"availability":"in_stock","featured":true,"isNew":false,"isSale":false}'::jsonb),
